"""Find the stretches of opening hours that nobody is covering."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

def _uncovered_spans(worked_spans: Iterable[Span], opening_hours: Span) -> List[Span]:
    cursor = opening_hours.start
    gaps = []
    for span in merge_spans(worked_spans):
        if span.start > cursor:
            gaps.append(Span(cursor, span.start))
        cursor = max(cursor, span.end)
    if cursor < opening_hours.end:
        gaps.append(Span(cursor, opening_hours.end))
    return gaps

# ---
def uncovered_gaps(worked_spans: Iterable[Span], opening_hours: Span) -> List[str]:
    """One label per stretch of opening hours that no worked span covers.

    Raises ValueError when any worked span falls outside opening hours.
    """
    worked = list(worked_spans)
    for span in worked:
        if span.start < opening_hours.start or span.end > opening_hours.end:
            raise ValueError(
                f"worked span {format_span(span)} is outside opening hours "
                f"{format_span(opening_hours)}"
            )
    return [
        f"gap {format_span(stretch)} ({stretch.minutes} min)"
        for stretch in _uncovered_spans(worked, opening_hours)
    ]

