# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import uncovered_gaps

class UncoveredGapTests(unittest.TestCase):
    def test_nobody_working_is_one_gap(self):
        self.assertEqual(
            uncovered_gaps([], Span(540, 1020)), ["gap 09:00-17:00 (480 min)"]
        )

    def test_lunch_gap(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 1020)), ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        worked = [Span(600, 900)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 1020)),
            ["gap 09:00-10:00 (60 min)", "gap 15:00-17:00 (120 min)"]
        )

    def test_touching_spans_leave_no_gap(self):
        worked = [Span(540, 600), Span(600, 1020)]
        self.assertEqual(uncovered_gaps(worked, Span(540, 1020)), [])

    def test_overlapping_spans_leave_no_gap(self):
        worked = [Span(540, 700), Span(650, 1020)]
        self.assertEqual(uncovered_gaps(worked, Span(540, 1020)), [])

    def test_unsorted_input(self):
        worked = [Span(780, 1020), Span(540, 720)]
        self.assertEqual(
            uncovered_gaps(worked, Span(540, 1020)), ["gap 12:00-13:00 (60 min)"]
        )

    def test_span_outside_hours_raises(self):
        cases = [
            [Span(480, 600)],
            [Span(1000, 1080)],
            [Span(540, 600), Span(1020, 1080)]
        ]
        for worked in cases:
            with self.subTest(worked=worked):
                with self.assertRaises(ValueError):
                    uncovered_gaps(worked, Span(540, 1020))

    def test_error_names_the_span(self):
        with self.assertRaisesRegex(ValueError, "08:00-10:00.*09:00-17:00"):
            uncovered_gaps([Span(480, 600)], Span(540, 1020))
